Here's an example C++ code to display total memory used by a specific process:
#include <windows.h>
#include <psapi.h>
#include <stdio.h>
void PrintMemoryInfo(DWORD processID)
{
    HANDLE hProcess;
    PROCESS_MEMORY_COUNTERS pmc;
    // Get a handle to the process.
    hProcess = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, processID);
    if (NULL == hProcess)
        return;
    // Get process memory information.
    if (GetProcessMemoryInfo(hProcess, &pmc, sizeof(pmc)))
    {
        printf("Total memory used: %ld\n", pmc.WorkingSetSize);
    }
    // Close the handle.
    CloseHandle(hProcess);
}
int main()
{
    // Replace the process ID with the desired process ID.
    DWORD processID = 1234;
    PrintMemoryInfo(processID);
    return 0;
}
For memory used by a specific component, you can use the same code and replace "WorkingSetSize" with "PrivateUsage". For percentage of memory usage, you can use the same code and calculate the percentage based on the total available memory on the system.

