What is the JavaScript code to output all the factors of a given number and indicate whether each factor is prime or composite? Specifically, for a given input number such as 24, how can the code output the factors 1, 2, 3, 4, 6, 8, 12, and 24, along with their respective prime or composite statuses? Please ensure that the solution involves a multi-step reasoning process and avoids the use of any external libraries. 
Here is an example JavaScript code that can achieve this:
function findFactors(num) {
  let factors = [];
  for (let i = 1; i <= num; i++) {
    if (num % i === 0) {
      factors.push(i);
    }
  }
  return factors;
}
function isPrime(num) {
  if (num < 2) {
    return false;
  }
  for (let i = 2; i < num; i++) {
    if (num % i === 0) {
      return false;
    }
  }
  return true;
}
function outputFactors(num) {
  let factors = findFactors(num);
  for (let i = 0; i < factors.length; i++) {
    let status = isPrime(factors[i]) ? "prime" : "composite";
    console.log(factors[i] + " (" + status + ")");
  }
}
outputFactors(24); // Output: 1 (composite), 2 (prime), 3 (prime), 4 (composite), 6 (composite), 8 (composite), 12 (composite), 24 (composite)

