class resign\_crypt
{
 public $CYPHER = 'rijndael-128';
 public $MODE = 'cfb';
 public $SALT = 'test';

 public function \_\_construct($CYPHER = null, $MODE = null, $SALT = null)
 {
 if ($CYPHER)
 {
 $this->CYPHER = $CYPHER;
 }
 if ($MODE)
 {
 $this->MODE = $MODE;
 }
 if ($SALT)
 {
 $this->SALT = $SALT;
 }
 }

 public function encryptMcrypt($plaintext, $password = '', $compress = true)
 {
 if ($compress)
 {
 $plaintext = gzdeflate($plaintext);
 }
 $td = mcrypt\_module\_open($this->CYPHER, '', $this->MODE, '');
 $iv = mcrypt\_create\_iv(mcrypt\_enc\_get\_iv\_size($td), MCRYPT\_RAND);
 $key = $this->SALT . trim($password);
 mcrypt\_generic\_init($td, $key, $iv);
 $crypttext = mcrypt\_generic($td, $plaintext);
 mcrypt\_generic\_deinit($td);
 $crypttext = $iv . $crypttext;
 return $crypttext;
 }

 public function decryptMcrypt($crypttext, $password = '', $decompress = true)
 {
 $td = mcrypt\_module\_open($this->CYPHER, '', $this->MODE, '');
 $ivsize = mcrypt\_enc\_get\_iv\_size($td);
 $iv = substr($crypttext, 0, $ivsize);
 $crypttext = substr($crypttext, $ivsize);
 $key = $this->SALT . trim($password);
 mcrypt\_generic\_init($td, $key, $iv);
 $plaintext = mdecrypt\_generic($td, $crypttext);
 if ($decompress)
 {
 $plaintext = gzinflate($plaintext);
 }
 return $plaintext;
 }
}

