	"golang.org/x/oauth2"
	"golang.org/x/oauth2/google"
)

type reCAPTCHAMiddleware struct {
	secretKey string
	next       http.Handler
}

func (m reCAPTCHAMiddleware) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if strings.HasPrefix(r.Header.Get("User-Agent"), "recaptcha") {
		token := r.Header.Get("zecaptcha-token")

		clientID := m.secretKey
		resp, err := verifyRecaptcha(clientID, token, r)
		if err != nil {
			log.Printf("reCAPTCHA verification error: %v", err)
			http.Error(w, "reCAPTCHA verification failed", http.StatusBadRequest)
			return
		}

		if !resp.Success {
			log.Printf("reCAPTCHA verification failed")
			http.Error(w, "reCAPTCHA verification failed", http.StatusBadRequest)
			return
		}
	}

	m.next.ServeHTTP(w, r)
}

func verifyRecaptcha(clientID, token string, r *http.Request) (*reCAPTCHAResponse, error) {
	baseURL := "https://www.google.com/recaptcha/api/siteverify"
	form := url.Values{
		"secret":   {clientID},
		"response": {token},
	}

	req, err := http.NewRequest("POST", baseURL, strings.NewReader(form.Encode()))
	if err != nil {
		return nil, err
	}

	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")

	client := &http.Client{Transport: &oauth2.TokenSource{AccessToken: accessTokenSource}}
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	return parseRecaptchaResponse(resp)
}

func parseRecaptchaResponse(resp *http.Response) (*reCAPTCHAResponse, error) {
	respBodyBytes, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	respBodyString := string(respBodyBytes)
	log.Printf("reCAPTCHA response: %s", respBodyString)

	var respData reCAPTCHAResponse
	err = json.Unmarshal(respBodyBytes, &respData)
	if err != nil {
		return nil, err
	}

	return &respData, nil
}

