```typescript
import * as PowerPoint from 'office-js';

function selectSlideRange(presentation: PowerPoint.Presentation, startSlideIndex: number, endSlideIndex: number) {
    // Get the slides in the presentation
    const slides = presentation.getSlides();

    // Check if the start slide index is valid
    if (startSlideIndex >= slides.count) {
        throw new Error('Start slide index is out of range');
    }

    // Check if the end slide index is valid
    if (endSlideIndex >= slides.count) {
        throw new Error('End slide index is out of range');
    }

    // Check if the start slide index is less than the end slide index
    if (startSlideIndex > endSlideIndex) {
        const temp = startSlideIndex;
        startSlideIndex = endSlideIndex;
        endSlideIndex = temp;
    }

    // Select the range of slides
    slides.getById(startSlideIndex).select();
    while (startSlideIndex !== endSlideIndex) {
        slides.getById(startSlideIndex).select(true);
        startSlideIndex++;
    }
    slides.getById(endSlideIndex).select(true);
}
```
This function takes in a PowerPoint presentation, a start slide index, and an end slide index as parameters. It uses the office-js library to interact with the PowerPoint presentation.

It first checks if the start and end slide indices are within the range of the total number of slides in the presentation. It then swaps the start and end slide indices if the start index is greater than the end index.

Finally, it selects the range of slides by first selecting the start slide, then looping through the slides until the end slide is reached, and finally selecting the end slide.

