    counter1, counter2 = Counter(word1), Counter(word2)

    if counter1 == counter2:
        return 'standard'
    elif all(v <= counter2[k] for k, v in counter1.items()):
        return 'subset'
    elif all(v >= counter2[k] for k, v in counter1.items()):
        return 'repeated'
    else:
        return None

def detect_and_classify_anagrams(input_phrases):
