Sure, here's an example of a custom ASP.NET Core middleware that can hide some fields from an action result object before it gets serialized to the output stream:
```csharp
using System.Linq;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Newtonsoft.Json;

public class HideFieldsMiddleware
{
    private readonly RequestDelegate _next;
    private readonly string[] _hiddenFields;

    public HideFieldsMiddleware(RequestDelegate next, string[] hiddenFields)
    {
        _next = next;
        _hiddenFields = hiddenFields;
    }

    public async Task Invoke(HttpContext context)
    {
        if (context.Request.Method == "POST" && context.Request.HasFormContentType)
        {
            var form = await context.ReadFormAsync();

            var actionResult = context.Items["ActionResult"] as ObjectResult;
            if (actionResult != null)
            {
                var values = form.ToDictionary(x => x.Key, x => x.Value);

                var json = JsonConvert.SerializeObject(actionResult.Value, new JsonSerializerSettings
                {
                    ContractResolver = new CamelCasePropertyNamesContractResolver(),
                    Formatting = Formatting.Indented,
                    MissingMemberHandling = MissingMemberHandling.Ignore
                });

                foreach (var field in _hiddenFields)
                {
                    var property = actionResult.Value.GetType().GetProperty(field);
                    if (property != null && property.CanRead)
                    {
                        json = json.Replace($"\"{field}\":{JsonConvert.SerializeObject(property.GetValue(actionResult.Value))}", "");
                    }
                }

                values["data"] = json;

                var newForm = new FormCollection(values);
                context.Request.Form = newForm;
            }
        }

        await _next(context);
    }
}
```
In this example, the middleware checks if the incoming request is a POST request and has a form content type. If so, it reads the form data and retrieves the "ActionResult" item from the HttpContext. It then checks if the action result is an instance of `ObjectResult`. If it is, it deserializes the JSON result into an object and iterates over the specified hidden fields (defined in the `_hiddenFields` array). For each hidden field, it removes the property from the JSON result before serializing it again. Finally, it updates the form data with the modified JSON result and passes it to the next middleware in the pipeline.

Here's an example of an ASP.NET Core middleware that hides some fields from an action result object before it gets serialized to the output stream:
```
public class HiddenFieldsMiddleware
{
    private readonly RequestDelegate _next;
    private readonly List<string> _hiddenFields = new List<string>();
    public HiddenFieldsMiddleware(RequestDelegate next)
    {
        _next = next;
    }
    public async Task Invoke(HttpContext context)
    {
        // Check if there are any hidden fields to hide
        if (_hiddenFields.Any())
        {
            // Get the action result object
            var result = context.Request.GetResult();
            // Remove the hidden fields from the action result object
            result.Value.AdditionalProperties = new Dictionary<string, object>()
            {
                { "_hiddenFields", _hiddenFields }
            };
            // Replace the action result object with the modified one
            var output = await _next.Invoke(context);
            // Serialize the output to the output stream
            context.Response.ContentType = "application/json";
            using (var stream = context.Response.Body)
            {
                await output.WriteToStreamAsync(stream);
            }
        }
    }
}
```
To use this middleware, add it to your application's middleware pipeline in the `Startup.cs` file:
```
public void Configure(IApplicationBuilder app, IEndpointSelectedFilter endpointSelectedFilter, IOptions<ApiBehaviorOptions> apiBehaviorOptions)
{
    app.UseMiddleware<HiddenFieldsMiddleware>();
}
```
This middleware listens for HTTP requests and checks if there are any hidden fields to hide. If there are, it removes them from the action result object and replaces the action result object with the modified one. The modified action result object is then passed to the next middleware in the pipeline.

