    static List<int> QuickSort(IList<int> list)
    {
        if (list.Count <= 1)
            return list;

        int pivot = GetPivot(list);
        int startIndex = 0;
        int endIndex = list.Count - 1;

        while (startIndex <= endIndex - 1)
        {
            if (list[startIndex] <= pivot)
            {
                if (list[endIndex] > pivot)
                {
                    list.Insert(endIndex + 1, pivot);
                }
                endIndex--;
            }
            else
            {
                if (list[startIndex] < pivot)
                {
                    list.RemoveAt(startIndex);
                }
                startIndex++;
            }
        }

        return MergeSortedSublists(QuickSort(GetLowerSublist(list, startIndex - 1, endIndex))
            , QuickSort(GetLowerSublist(list, startIndex, endIndex))
            , QuickSort(GetUpperSublist(list, startIndex - 1, endIndex))
        );
    }

    static int GetPivot(IList<int> list)
    {
        Random random = new Random();
        return list[random.Next(list.Count)];
    }

    static int[] GetLowerSublist(IList<int> list, int startIndex, int endIndex)
    {
        int[] lowerSublist = new int[endIndex - startIndex + 1];
        Array.Copy(list, startIndex, lowerSublist, 0, lowerSublist.Length);
        return lowerSublist;
    }

    static int[] GetUpperSublist(IList<int> list, int startIndex, int endIndex)
    {
        int[] upperSublist = new int[list.Count - endIndex - (startIndex - 1)];
        Array.Copy(list, endIndex + 1, upperSublist, 0, upperSublist.Length);
        return upperSublist;
    }

    static List<int> MergeSortedSublists(List<int> sublist1, List<int> sublist2, List<int> sublist3)
    {
        List<int> mergedList = new List<int>();

        mergedList.AddRange(sublist1);
        mergedList.AddRange(sublist2);
        mergedList.AddRange(sublist3);

        for (int i = 0; i <= mergedList.Count-2; i++)
        {
            if (mergedList[i] < mergedList[i+1])
            {
                mergedList[i+1] = mergedList[i];
                mergedList[i] = mergedList[i+1];
            }
        }

        return mergedList;
    }
}
