public static void Sort(int[] list)
{
    if (list.Length < 2)
    {
        return;
    }

    int leftIndex = 0;
    int rightIndex = list.Length - 1;

    while (leftIndex <= rightIndex)
    {
        int midIndex = (leftIndex + rightIndex) / 2;
        int item = list[midIndex];

        if (item < list[rightIndex])
        {
            list[leftIndex] = item;
            leftIndex++;
        }
        else if (item > list[leftIndex])
        {
            list[rightIndex] = item;
            rightIndex--;
        }
        else
        {
            list[rightIndex] = item;
            rightIndex--;
        }
    }

    int i = list.Length - 1;
    while (i >= 0)
    {
        int j = i - 1;
        while (j >= 0 && list[j] > list[i])
        {
            list[i + 1] = list[j];
            j--;
        }
        list[i + 1] = list[i];
        i--;
    }
}


