import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

public class TimeWindow {

    private LocalDateTime windowStartTime;
    private LocalDateTime windowEndTime;

    public TimeWindow(LocalDateTime startTime, LocalDateTime endTime) {
        this.windowStartTime = startTime;
        this.windowEndTime = endTime;
    }

    public boolean isWithinWindow(LocalDateTime time) {
        return time.isAfter(this.windowStartTime) && time.isBefore(this.windowEndTime);
    }
}

public class TimeWindowRunner {

    public static TimeWindow runnerWindow(String startTime, String endTime) {
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("HH:mm");
        LocalDateTime start = LocalDateTime.parse(startTime, formatter);
        LocalDateTime end = LocalDateTime.parse(endTime, formatter);
        return new TimeWindow(start, end);
    }

    public static boolean runIfWithinWindow(LocalDateTime time, TimeWindow window) {
        if (window.isWithinWindow(time)) {
            return true;
        } else {
            return false;
        }
    }

    public static void doArbitraryCode(TimeWindow window, Runnable code) {
        if (runIfWithinWindow(LocalDateTime.now(), window)) {
            code.run();
        }
    }
}

