To create a webpage that accurately calculates the distance between the user's location and the nearest Italian restaurant while taking into account the user's preferences and the restaurant's popularity, you can follow these steps:

1. Acquire user's location using the browser's Geolocation API.
2. Store dataset containing the Italian restaurants' location coordinates, cuisine type, and popularity.
3. Calculate the distance between the user's location and each restaurant.
4. Filter restaurants based on user's preferences (e.g., cuisine type, popularity threshold).
5. Calculate the nearest restaurant among the filtered list and display its details on the page.

Here's an example HTML page that implements this algorithm:

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Find Nearest Italian Restaurant</title>
<script>
function findRestaurant() {
    // Step 1: Acquire user's location
    if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(processCoordinates);
    } else {
        alert("Geolocation is not supported by this browser.");
    }
}

function processCoordinates(position) {
    let lat1 = position.coords.latitude;
    let lon1 = position.coords.longitude;
    let filteredRestaurants = [];

    // Step 2: Store dataset containing restaurant's coordinates, cuisine type, and popularity
    let restaurants = [
        {name: 'Italian Restaurant A', latitude: 40.730610, longitude: -73.935242, cuisine: 'Pizza', popularity: 4},
        {name: 'Italian Restaurant B', latitude: 40.731890, longitude: -73.998992, cuisine: 'Pasta', popularity: 5},
        // more restaurant data ...
    ];

    // Step 3: Calculate distance between user's location and each restaurant
    restaurants.forEach(function(restaurant) {
        let lat2 = restaurant.latitude;
        let lon2 = restaurant.longitude;
        let R = 6371; // Earth's radius in km

        let dLat = ((lat2 - lat1) * Math.PI) / 180;
        let dLon = ((lon2 - lon1) * Math.PI) / 180;
        let a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
                Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
                Math.sin(dLon / 2) * Math.sin(dLon / 2);
        let c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        let d = R * c; // Distance in km

        restaurant.distance = d;
    });

    // Step 4: Filter based on user's preferences
    let minPopularity = 4; // minimum popularity to filter restaurants (1-5)
    let selectedCuisine = 'Pizza'; // selected cuisine by user

    filteredRestaurants = restaurants.filter(r => r.popularity >= minPopularity && r.cuisine === selectedCuisine);

    // Step 5: Calculate the nearest restaurant
    let nearest = filteredRestaurants.reduce(function(min, restaurant) {
        return restaurant.distance < min.distance ? restaurant : min;
    }, filteredRestaurants[0]);

    // Display the result
    document.getElementById("result").innerHTML = `Nearest Italian Restaurant: ${nearest.name}, Distance: ${nearest.distance.toFixed(2)} km`;
}
</script>
</head>
<body>

