                if ($i > 0 && isset($previousIteration[$table])) {
                    foreach ($previousIteration[$table] as $prevName) {
                        if (in_array($prevName, $currentTable)) {
                            $hasDuplicate = true;
                            break;
                        }
                    }
                }

                // If there was a duplicate, reshuffle the names and restart seating for the table
                if ($hasDuplicate) {
                    shuffle($names);
                    $table--;
                    break;
                } else {
                    $currentTable[] = $name;
                }
            }

            if (!$hasDuplicate) {
                $currentIteration[] = $currentTable;
            }
        }

        $previousIteration = $currentIteration;
        $allocations[] = $currentIteration;
    }

    return $allocations;
}

