#include <string.h>

void parse_string(const char *input, const char *delimiter)
{
    // Create a copy of the input string to modify it with strtok()
    char *str = strdup(input);
    if (str == NULL)
    {
        printf("Memory allocation for string copy failed.\n");
        return;
    }

    // Parse the string using strtok()
    char *token = strtok(str, delimiter);
    while (token != NULL)
    {
        printf("Token: %s\n", token);
        token = strtok(NULL, delimiter);
    }

    // Free the copied string
    free(str);
}

