    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Name Converter</title>
    <style>
        body {
            font-family: Arial, sans-serif;
        }
        #inputContainer {
            margin-bottom: 20px;
        }
        #output {
            width: 100%;
            height: 200px;
            resize: none;
        }
